const CACHE='family-shell-v20';
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(['/','/style.css','/interface.css','/interface.mjs','/albums.mjs','/app.js','/community.mjs','/social.mjs','/family.mjs','/viewport.mjs','/storage-admin.mjs','/notifications.mjs','/mentions.mjs','/profile-links.mjs','/launch.mjs','/family-logo.png','/icon-512.png','/auth-callback.mjs','/announcement-time.mjs','/announcement-layout.mjs','/icon.svg','/manifest.webmanifest']))));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k))))));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).catch(()=>caches.match(e.request).then(r=>r||new Response('يلزم الاتصال بالإنترنت',{status:503}))));});
self.addEventListener('push',event=>{let data={};try{data=event.data.json()}catch{}const target=data.url==='/?open=chat'?'/?open=chat':'/?open=news';event.waitUntil(self.registration.showNotification('أخبار العائلة',{body:data.body||'لديك تحديث جديد في أخبار العائلة.',icon:'/icon-192.png',badge:'/icon-192.png',tag:data.tag||'family-update',data:{url:target}}));});
self.addEventListener('notificationclick',event=>{event.notification.close();const target=new URL(event.notification.data?.url||'/?open=news',self.location.origin).href;event.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(async windows=>{for(const client of windows){if(new URL(client.url).origin===self.location.origin){await client.navigate(target);return client.focus();}}return clients.openWindow(target);}));});
